Import ListNotations.
Open Scope Z_scope.
Local Ltac addr_near k ::= let inb := eval vm_compute in (andb (Z.leb 0 k) (Z.ltb k 8192))%Z in lazymatch inb with true => idtac end.   (* [comment removed for export] *)
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.

Ltac showpc := match goal with |- evt _ _ (MS _ _ ?pc _ _ _ _) => idtac "PC:" pc end.

(* [comment removed for export] *)
Definition unreg_got (m : mem) : Prop :=
  ro_cells asegs m 0x10ab40 [C8 (Z_to_bv 64 0x1a9820)]
  /\ ro_cells asegs m 0x10ab50 [C8 (Z_to_bv 64 0x1ab8a8); C8 (Z_to_bv 64 0x117578); C8 (Z_to_bv 64 0x119d78);
                               C8 (Z_to_bv 64 0x11aa68); C8 (Z_to_bv 64 0x11aa70); C8 (Z_to_bv 64 0x11aa60);
                               C8 (Z_to_bv 64 0x10ca40)].

Definition unreg_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(bv_unsigned sp - 240, bv_unsigned sp); (0x117630, 0x117638);
              (XS1_LO, XS1_HI); (XS2_LO, XS2_HI); (XS3_LO, XS3_HI); (0x64c402, 0x64c404); (0x64c400, 0x64c402)] m m'
    /\ wmono asegs m m' /\ mem_inv asegs m' /\ stk asegs m' lo (bv_unsigned sp).

Lemma unreg_spec : forall ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (lo : Z) (o1 o2 o3 o4 : byte),
  a0 = Z_to_bv 64 0x10f580 -> a1 = Z_to_bv 64 453 ->
  stk asegs m lo (bv_unsigned sp) -> lo <= bv_unsigned sp - 240 -> 0x800c0000 <= lo ->
  unreg_got m ->
  ro_cells asegs m 0x117590 [C4 (Z_to_bv 64 1)] ->
  rw_cells asegs m 0x117630 [C8 (Z_to_bv 64 0)] ->
  ro_cells asegs m 0x119d78 [C8 (Z_to_bv 64 0x7fff8000)] ->
  rw_cells asegs m 0x11aa58 [C1 (Z_to_bv 8 1)] ->
  ro_cells asegs m 0x1195dc [C1 (Z_to_bv 8 1)] ->
  ro_cells asegs m 0x1ab920 [C8 (Z_to_bv 64 0xffffffffffffffff)] ->
  ro_cells asegs m 0x10ca40 [C8 (Z_to_bv 64 0x1012a0)] ->
  stk asegs m XS1_LO XS1_HI -> stk asegs m XS2_LO XS2_HI -> stk asegs m XS3_LO XS3_HI ->
  gds_at m 0x10f580 asan_gds ->
  rw_cells asegs m 0x64c402 [C1 o1] -> rw_cells asegs m 0x64c400 [C1 o2] -> rw_cells asegs m 0x64c401 [C1 o3] -> rw_cells asegs m 0x64c403 [C1 o4] ->
